diff --git a/internal/server/server.go b/internal/server/server.go
index 09085c2..f24340e 100644
--- a/internal/server/server.go
+++ b/internal/server/server.go
@@ -97,9 +97,18 @@ func (s *Server) routes() {
 	s.mux.HandleFunc("GET /api/me", s.requireUser(func(w http.ResponseWriter, _ *http.Request, u *store.User) {
 		writeJSON(w, http.StatusOK, map[string]any{"id": u.ID, "email": u.Email})
 	}))
+	// A logged-in user creates a link, lists their own with click counts
+	// and deletes their own.
+	s.mux.HandleFunc("POST /api/links", s.requireUser(s.createLink))
+	s.mux.HandleFunc("GET /api/links", s.requireUser(s.listLinks))
+	s.mux.HandleFunc("DELETE /api/links/{slug}", s.requireUser(s.deleteLink))
 	s.mux.Handle("/api/", http.NotFoundHandler())
 	s.mux.Handle("/app/", http.StripPrefix("/app", app()))
 	s.mux.Handle("GET /{$}", http.RedirectHandler("/app/", http.StatusFound))
+	// GET /<slug> is the short URL: it redirects to the target and counts
+	// the click. The paths above are longer or more specific, so only an
+	// unreserved single segment reaches it.
+	s.mux.HandleFunc("GET /{slug}", s.redirect)
 }

